class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> ans;
        string cur;
        cur.reserve(2 * n);
        dfs(n, 0, 0, cur, ans);
        return ans;
    }
private:
    void dfs(int n, int open, int close, string &cur, vector<string> &ans) {
        if (open == n && close == n) {
            ans.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            dfs(n, open + 1, close, cur, ans);
            cur.pop_back();
        }
        if (close < open) {
            cur.push_back(')');
            dfs(n, open, close + 1, cur, ans);
            cur.pop_back();
        }
    }
};
